async function peer(protocol=S.PROTOCOL){const messages=[],waiting=[];const socket=net.connect(address.port,'127.0.0.1');await new Promise((r,j)=>{socket.once('connect',r);socket.once('error',j);});let buffer='';socket.setEncoding('utf8');socket.on('data',b=>{buffer+=b;let end;while((end=buffer.indexOf('\n'))>=0){const m=JSON.parse(buffer.slice(0,end));buffer=buffer.slice(end+1);messages.push(m);for(const w of [...waiting])if(w.predicate(m)){waiting.splice(waiting.indexOf(w),1);clearTimeout(w.timer);w.resolve(m);}}});const p={socket,messages,send:m=>socket.write(JSON.stringify(m)+'\n'),next:(predicate,timeout=6000)=>new Promise((resolve,reject)=>{const w={predicate,resolve,timer:setTimeout(()=>reject(Error('Network message timed out: '+predicate.toString())),timeout)};waiting.push(w);})};peers.push(p);const welcome=p.next(m=>m.type==='welcome'||m.type==='error');p.send({type:'hello',protocol,name:'Tester'});const response=await welcome;if(protocol===S.PROTOCOL)assert.equal(response.protocol,S.PROTOCOL);else assert.match(response.message,/Protocol version mismatch/);return p;}
